<script setup lang="ts">
import {computed,nextTick,onUnmounted,ref,watch} from 'vue';
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';
import FeedbackTableView from './FeedbackTableView.vue';import {useFeedbackSubmission} from './useFeedbackSubmission';
import type {Feedback,FeedbackOverview} from '../../shared/api/feedback';
const app=useApplication(),actions=app.feedbackActions,route=useRoute(),router=useRouter();
const actor=()=>app.session.current.value?.actor.enterpriseId??null,admin=computed(()=>app.session.current.value?.actor.roles.includes('PLATFORM_ADMIN')??false);
const emptyCounts=()=>({ALL:0,PENDING:0,ACCEPTED:0,REJECTED:0,NEEDS_MORE:0});
const overview=ref<FeedbackOverview>({items:[],nextCursor:null,counts:emptyCounts()}),selected=ref<Feedback['state']|null>(null),reviewing=ref(false),loading=ref(false),error=ref<string|null>(null),profile=ref<{displayName:string;department:string|null}|null>(null),menu=ref<HTMLDetailsElement>();
const profileName=computed(()=>profile.value?.displayName||actor()||'尚未登录'),localDevelopment=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_DEV_LOGIN==='1';
let identityEpoch=0,epoch=0,request:AbortController|null=null,cursors:(string|null)[]=[null];
async function load(cursor:string|null=cursors.at(-1)??null){const who=actor(),turn=++epoch;request?.abort();const controller=new AbortController();request=controller;loading.value=true;error.value=null;try{const value=await app.feedback.summaries(cursor,selected.value,reviewing.value,controller.signal);if(turn===epoch&&actor()===who&&!controller.signal.aborted)overview.value=value;}catch(cause){if(turn===epoch&&actor()===who&&!controller.signal.aborted){overview.value={items:[],nextCursor:null,counts:emptyCounts()};error.value=cause instanceof Error?cause.message:'反馈列表暂不可用。';}}finally{if(turn===epoch)loading.value=false;}}
function first(){cursors=[null];return load(null);}
function filter(state:Feedback['state']|null){selected.value=state;void first();}
function toggleReview(){if(!admin.value||actions.pending.value)return;reviewing.value=!reviewing.value;selected.value=null;menu.value?.removeAttribute('open');void router.replace({query:{...route.query,reviewing:reviewing.value?'1':undefined}});void first();}
function next(){if(!overview.value.nextCursor||loading.value)return;cursors.push(overview.value.nextCursor);void load();}
function previous(){if(cursors.length<2||loading.value)return;cursors.pop();void load();}
const submission=useFeedbackSubmission(app.feedback,actor,app.journals),submitDialog=ref<HTMLDialogElement>(),submitBusy=ref(false),submitMeeting=ref(''),submitCategory=ref('WORDING'),submitComment=ref(''),composing=ref(false);
const submissionLocked=computed(()=>submission.command.snapshot.value!==null),detailDialog=ref<HTMLDialogElement>(),detailVisible=ref(false),detailError=ref<string|null>(null),supplement=ref(''),reviewReason=ref(''),decision=ref('NEEDS_MORE');
const notice=ref<{title:string;body:string}|null>(null),noticeDialog=ref<HTMLDialogElement>();async function showNotice(title:string,body:string){notice.value={title,body};await nextTick();noticeDialog.value?.showModal();}
const stateLabels:Record<string,string>={PENDING:'待审核',ACCEPTED:'已通过',REJECTED:'已驳回',NEEDS_MORE:'需要补充'},historyLabels:Record<string,string>={SUPPLEMENT:'补充说明',REVIEW:'审核结论',UNDO_REVIEW:'撤销审核'};function localTime(value:string){const date=new Date(value);return Number.isFinite(+date)?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(date):'时间暂不可用';}
const detail=actions.detail,locked=computed(()=>actions.pending.value||actions.busy.value),canLeave=()=>!actions.pending.value&&!actions.busy.value&&!submissionLocked.value&&!submitBusy.value;
function failure(cause:unknown){detailError.value=cause instanceof Error?cause.message:'反馈处理尚未确认，请保留原请求。';}
async function openDetail(id:string){const who=actor(),turn=identityEpoch;if(!who||submissionLocked.value)return;detailError.value=null;detailVisible.value=true;await nextTick();if(actor()!==who||turn!==identityEpoch)return;if(!detailDialog.value?.open)detailDialog.value?.showModal();try{await actions.open(id);if(actor()===who&&turn===identityEpoch&&actions.available.value)await router.replace({query:{...route.query,feedbackId:id}});}catch(cause){failure(cause);}}
function closeDetail(){if(!locked.value){detailDialog.value?.close();detailVisible.value=false;supplement.value='';reviewReason.value='';detailError.value=null;}}
async function run(action:()=>Promise<unknown>){if(composing.value||actions.busy.value)return;detailError.value=null;try{await action();supplement.value='';reviewReason.value='';await load();}catch(cause){failure(cause);}}
async function discard(){try{actions.discardRejected();await actions.reload();detailError.value=null;}catch(cause){failure(cause);}}
async function openSubmit(){const who=actor(),turn=identityEpoch;if(!who||actions.pending.value)return;menu.value?.removeAttribute('open');error.value=null;try{submitMeeting.value=typeof route.query.meetingId==='string'?route.query.meetingId:submitMeeting.value;const restored=submission.open(submitMeeting.value);if(restored){submitMeeting.value=restored.meetingId;submitCategory.value=restored.category;submitComment.value=restored.comment;}await nextTick();if(actor()===who&&turn===identityEpoch)submitDialog.value?.showModal();}catch(cause){error.value=cause instanceof Error?cause.message:'反馈原请求暂不可用。';}}
function closeSubmit(){if(!submitBusy.value&&!submissionLocked.value){submitDialog.value?.close();submitComment.value='';}}
async function submit(){if(submitBusy.value||composing.value)return;submitBusy.value=true;try{if(!submission.available.value)submission.open(submitMeeting.value);await router.replace({query:{...route.query,meetingId:submitMeeting.value}});await submission.submit({meetingId:submitMeeting.value,category:submitCategory.value,comment:submitComment.value});submitComment.value='';submitDialog.value?.close();await router.replace({query:{...route.query,meetingId:undefined}});await first();}catch(cause){error.value=cause instanceof Error?cause.message:'反馈尚未确认，请保留原请求。';}finally{submitBusy.value=false;}}
function discardSubmission(){try{submission.discardRejected();error.value=null;}catch(cause){error.value=cause instanceof Error?cause.message:'原反馈暂无法清理。';}}

const stopPrivacy=watch(()=>actions.available.value,ready=>{if(!ready){supplement.value='';reviewReason.value='';}},{flush:'sync'});
const stopIdentity=watch(actor,who=>{identityEpoch++;epoch++;request?.abort();overview.value={items:[],nextCursor:null,counts:emptyCounts()};profile.value=null;error.value=null;detailError.value=null;detailVisible.value=false;detailDialog.value?.close();submitDialog.value?.close();submission.dispose();submitComment.value='';supplement.value='';reviewReason.value='';reviewing.value=Boolean(who&&admin.value&&route.query.reviewing==='1');selected.value=null;cursors=[null];if(who){void first();const captured=who;void app.options.people(who,null,new AbortController().signal).then(value=>{if(actor()===captured)profile.value=value.items.find(p=>p.stableId===captured)??null;}).catch(()=>{});}},{immediate:true,flush:'sync'});
const stopPending=watch(()=>actions.pending.value,pending=>{if(!pending)return;if(admin.value&&actions.command.snapshot.value?.operation!=='FEEDBACK_SUPPLEMENT')reviewing.value=true;const body=actions.original.value;if(body){supplement.value=typeof body.text==='string'?body.text:'';reviewReason.value=typeof body.reason==='string'?body.reason:'';decision.value=typeof body.decision==='string'?body.decision:'NEEDS_MORE';}const id=actions.command.snapshot.value?.resource;if(id&&!detailVisible.value)void openDetail(id);},{immediate:true,flush:'post'});
const stopQuery=watch(()=>[route.query.feedbackId,route.query.meetingId],async([id,meeting])=>{if(typeof id==='string'&&!detailVisible.value&&!actions.pending.value)await openDetail(id);else if(typeof meeting==='string'&&!id&&!submitDialog.value?.open&&!actions.pending.value)await openSubmit();},{immediate:true});
onBeforeRouteLeave(()=>canLeave());onBeforeRouteUpdate((to,from)=>to.query.feedbackId===from.query.feedbackId&&to.query.meetingId===from.query.meetingId||canLeave());
onUnmounted(()=>{epoch++;request?.abort();stopPending();stopPrivacy();stopIdentity();stopQuery();submission.dispose();});
</script>
<template><div class="layout"><div class="main">
 <header class="topbar"><nav class="topbar-heading"><RouterLink to="/meetings" class="topbar-home"><Icon name="list"/> 我的会议</RouterLink><span class="topbar-crumb">/ 我的语料反馈</span></nav><div class="topbar-right">
  <button class="btn sm ghost" @click="router.push('/feedback')"><Icon name="message" :size="15"/> 我的语料反馈</button><button class="btn sm ghost" @click="showNotice('演示引导','从当前用户菜单提交反馈，或打开已有建议查看详情和补充说明。')"><Icon name="guide" :size="15"/> 演示引导</button><button class="btn sm ghost" @click="showNotice('重置演示数据','反馈保存在数据库中，此入口不删除已提交反馈。可从当前用户菜单重新读取当前反馈。')"><Icon name="reset" :size="15"/> 重置演示数据</button>
  <details ref="menu" class="feedback-profile"><summary class="role-chip" aria-label="当前用户"><div class="avatar o">{{Array.from(profileName)[0]}}</div><div><div class="rc-name">{{profileName}}</div><div class="rc-role">会议负责人 · {{profile?.department??'--'}}</div></div></summary><div class="feedback-menu"><button class="btn sm ghost" @click="openSubmit">提交反馈</button><button class="btn sm ghost" @click="first">重新读取反馈</button><button v-if="admin" class="btn sm ghost" @click="toggleReview">{{reviewing?'返回我的反馈':'反馈审核队列'}}</button><a class="btn sm ghost" href="/auth/cas/logout">退出登录</a></div></details>
 </div></header><main class="content">
  <div v-if="reviewing" class="banner info">正在审核用户主动提交的反馈。本次审核仅记录处理结论；企业语料更新尚未开通。</div>
  <FeedbackTableView :items="overview.items" :counts="overview.counts" :selected="selected" :loading="loading" :error="error??app.feedbackScopeError.value" @select="filter" @open="openDetail"/>
  <div v-if="overview.nextCursor||cursors.length>1" class="pager"><button :disabled="loading||cursors.length<2" @click="previous">上一页反馈</button><button :disabled="loading||!overview.nextCursor" @click="next">下一页反馈</button></div>
  <button v-if="error" class="btn" @click="first">重新读取反馈</button>
  <div v-if="localDevelopment" class="demo-note">当前页面数据均为产品演示用模拟数据，不代表招商基金真实业务信息。<br>当前原型为纯前端交互演示，不连接招商基金真实业务系统。当前原型仅展示会议负责人的相关功能。</div>
 </main>
 <dialog ref="detailDialog" class="mask feedback-dialog-root" aria-label="反馈详情" @cancel.prevent="closeDetail"><div class="modal lg"><header class="modal-h"><h3 class="m-t">反馈详情</h3><button class="m-x" :disabled="locked" aria-label="关闭反馈详情" @click="closeDetail"><Icon name="x" :size="18"/></button></header><div class="modal-b">
  <p v-if="detailError" class="banner error" role="alert">{{detailError}}</p><p v-if="actions.busy.value" role="status">正在核实当前反馈…</p>
  <template v-if="detail&&actions.available.value"><dl><dt>来源会议</dt><dd class="mono">{{detail.feedback.meetingId}}</dd><dt>原始反馈</dt><dd class="feedback-copy">{{detail.feedback.comment}}</dd><dt>当前状态</dt><dd>{{stateLabels[detail.feedback.state]}}</dd><dt>审核意见</dt><dd>{{detail.reviewReason??'等待平台管理员审核'}}</dd></dl>
   <ol aria-label="反馈处理历史"><li v-for="item in detail.history" :key="item.id"><span>{{localTime(item.createdAt)}} · {{historyLabels[item.action]}} · {{item.actorId}}</span><p class="feedback-copy">{{item.text||'撤销审核，恢复待审核'}}</p></li></ol>
   <template v-if="!reviewing"><div class="field"><label for="feedback-supplement">补充说明</label><textarea id="feedback-supplement" v-model="supplement" class="input" rows="3" maxlength="4096" :readonly="locked" @compositionstart="composing=true" @compositionend="composing=false"></textarea></div><button class="btn primary" :disabled="locked||composing||!supplement.trim()" @click="run(()=>actions.supplement(supplement))">提交补充</button></template>
   <template v-if="admin&&reviewing"><div class="banner info">审核反馈不会授予来源会议的访问权限；审核通过只记录当前处理结论。</div><div class="field"><label for="feedback-review-decision">审核结论</label><select id="feedback-review-decision" v-model="decision" class="select" :disabled="locked"><option value="ACCEPTED">通过</option><option value="REJECTED">驳回</option><option value="NEEDS_MORE">需要补充</option></select></div><div class="field"><label for="feedback-review-reason">审核意见</label><textarea id="feedback-review-reason" v-model="reviewReason" class="input" rows="3" maxlength="2048" :readonly="locked" @compositionstart="composing=true" @compositionend="composing=false"></textarea></div><button v-if="detail.feedback.state==='PENDING'" class="btn primary" :disabled="locked||composing||!reviewReason.trim()" @click="run(()=>actions.review(decision,reviewReason))">提交审核</button><button v-else class="btn" :disabled="locked||composing" @click="run(actions.undo)">撤销审核</button></template>
  </template><p v-if="actions.pending.value" class="small muted" role="status">原反馈处理请求已保留，当前内容只读。</p>
 </div><footer class="modal-f"><button v-if="actions.pending.value&&['CONFLICT','REJECTED'].includes(actions.command.state.value)" class="btn" :disabled="actions.busy.value" @click="discard">放弃已拒绝的原请求</button><button class="btn" :disabled="locked" @click="closeDetail">关闭</button><button v-if="actions.pending.value" class="btn primary" :disabled="actions.busy.value||!actions.available.value||!['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(actions.command.state.value)" @click="run(actions.retry)">{{actions.command.state.value==='ACKNOWLEDGED'?'重新核实已受理反馈':'重试原反馈处理'}}</button></footer></div></dialog>
 <dialog ref="submitDialog" class="mask feedback-dialog-root" aria-label="提交语料反馈" @cancel.prevent="closeSubmit"><div class="modal"><header class="modal-h"><h3 class="m-t">提交语料反馈</h3><button class="m-x" :disabled="submitBusy||submissionLocked" aria-label="关闭提交反馈" @click="closeSubmit"><Icon name="x" :size="18"/></button></header><div class="modal-b"><p v-if="error" class="banner error" role="alert">{{error}}</p><div class="field"><label for="feedback-source-meeting">来源会议编号</label><input id="feedback-source-meeting" v-model="submitMeeting" class="input" :readonly="submitBusy||submissionLocked"/></div><div class="field"><label for="feedback-category">反馈类型</label><select id="feedback-category" v-model="submitCategory" class="select" :disabled="submitBusy||submissionLocked"><option value="WORDING">文字</option><option value="LABEL">标签</option><option value="ACTION_OWNER">行动负责人</option></select></div><div class="field"><label for="feedback-comment">反馈内容</label><textarea id="feedback-comment" v-model="submitComment" rows="4" class="input" maxlength="4096" :readonly="submitBusy||submissionLocked" @compositionstart="composing=true" @compositionend="composing=false"></textarea></div></div><footer class="modal-f"><button class="btn" :disabled="submitBusy||submissionLocked" @click="closeSubmit">取消</button><button v-if="['CONFLICT','REJECTED'].includes(submission.command.state.value)" class="btn" @click="discardSubmission">放弃已拒绝的原反馈</button><button class="btn primary" :disabled="submitBusy||composing||!submitComment.trim()" @click="submit">{{submissionLocked?'重试原反馈':'提交'}}</button></footer></div></dialog>
<dialog ref="noticeDialog" class="notice-dialog"><form method="dialog"><h2>{{notice?.title}}</h2><p>{{notice?.body}}</p><button class="btn primary">知道了</button></form></dialog>
</div></div></template>
<style scoped>.feedback-profile{position:relative}.feedback-profile>summary{cursor:pointer;list-style:none}.feedback-profile>summary::-webkit-details-marker{display:none}.feedback-menu{position:absolute;right:0;top:calc(100% + 4px);z-index:45;display:flex;flex-direction:column;align-items:stretch;min-width:150px;padding:8px;background:white;border:1px solid var(--border);border-radius:8px;box-shadow:var(--shadow-lg)}.feedback-dialog-root{inset:0;border:0;padding:24px;margin:0;width:100vw;height:100dvh;max-width:none;max-height:none;color:var(--text)}.feedback-dialog-root:not([open]){display:none}.feedback-dialog-root::backdrop{background:transparent}.feedback-dialog-root .input{width:100%}.feedback-copy{white-space:pre-wrap;overflow-wrap:anywhere}.m-t{margin:0}dt{color:var(--muted)}dd{margin:4px 0 12px}</style>
